import {FeedbackView} from '../../src/features/feedback.ts';import {HelpView} from '../../src/features/help.ts';
export function createFeedbackFixture(){let calls:any[]=[],confirmations:any[]=[],confirm=true,fail=false,pending=false,result:'sent'|'cancelled'|'unknown'='sent',resolve:((r:any)=>void)|undefined,cancels=0;const view=new FeedbackView([{id:'abcdef123456',name:'实验 <标签>',sourceId:'官方实验名'}],{submit:async input=>{calls.push(input);if(fail)throw Error('模拟服务不可用');if(pending)return new Promise<any>(r=>resolve=r);return {state:result};},cancel:async()=>{cancels++;resolve?.({state:'cancelled'})},confirm:async(text,experiment)=>{confirmations.push({text,experiment});return confirm;}});const mount=()=>view.mount(document.querySelector<HTMLElement>('#feedback-host')!);mount();return {state:()=>({calls,confirmations,cancels,busy:view.isSaving}),confirm:(v:boolean)=>confirm=v,fail:(v:boolean)=>fail=v,result:(r:typeof result)=>result=r,pending:()=>pending=true,resolve:()=>resolve?.({state:'sent'}),leave:()=>view.leave(),reopen:mount};}
export function help(){const view=new HelpView();view.mount(document.querySelector<HTMLElement>('#feedback-host')!);return view;}
